"answer": 0,
"explanation": "民法の制限行為能力者制度に基づき、アとイが正しい。\n\nア：正しい。民法第5条第2項により、未成年者が法定代理人の同意なく行った法律行為は、未成年者本人または法定代理人が取り消すことができる。\nイ：正しい。民法第9条ただし書きにより、成年被後見人が日用品の購入その他日常生活に関する行為については後見人は取り消すことができない。\nウ：誤り。被保佐人が保佐人の同意なく行った重要な財産行為（民法第13条第1項）は取消し可能であり、当然無効ではない。\nエ：誤り。民法第21条により、制限行為能力者が能力者であることを信じさせるために詐術を用いた場合は取消しができなくなる。\n\n【頻出】日用品購入の取消不可（民法第9条但書）は成年被後見人のみに適用。未成年者・被保佐人・被補助人には同様の規定の範囲が異なる。\n【混同注意】制限行為能力者の行為は「無効」ではなく「取消し可能」が原則。詐術を用いた場合のみ例外的に取消し不可。"
