"answer": 1,
"explanation": "会社法第828条第1項第2号により、募集株式の発行等の無効の訴えは、公開会社においては効力発生日から6ヶ月以内、非公開会社においては効力発生日から1年以内に提起しなければならない（出訴期間の制限）。\n\nA：誤り。新株発行の差止めは会社法第210条に基づき新株発行「前」に差止請求（仮処分申請等）を行うものであるが、本設問の「差止めを申立てることができない（発行後は不可）」という点は事実。発行が完了した後は「無効の訴え」の問題となる（新株発行差止めと無効の訴えの区別）。\nC：誤り。会社法第210条第2号により、新株発行が「著しく不公正な方法により行われる場合」は差止め事由の一つとして規定されている。「差止め事由にならない」は誤り（有利発行でない場合でも著しく不公正な方法による場合は差止め可能）。\nD：誤り。会社法第839条により、新株発行無効の判決が確定した場合でも、その効果は将来に向かって生じるのみ（将来効）であり、発行時に遡及して無効とはならない（既存の取引の安全保護・法律関係の安定化）。\n\n【頻出】新株発行の差止め（事前・会社法第210条：法令定款違反または著しく不公正な方法）と新株発行無効の訴え（事後・出訴期間：公開会社6ヶ月・非公開会社1年・将来効）の対比は頻出。\n【混同注意】新株発行差止め（発行前の事前救済・差止め事由あり）と新株発行無効の訴え（発行後の事後救済・厳格な出訴期間・将来効）の2段階の救済制度の違いを整理する。"
